SELECT qna_id AS qnaId, product_id AS productId, store_id AS storeId, writer_user_id AS writerUserId, title, content, qna_category AS qnaCategory, is_private AS isPrivate, status, answer_user_id AS answerUserId, answer_content AS answerContent, answered_at AS answeredAt, created_date AS createdDate, updated_date AS updatedDate FROM PRODUCT_QNA WHERE product_id = #{productId}
AND qna_category = #{qnaCategory}
ORDER BY created_date DESC

SELECT store_id
FROM PRODUCT_QNA
WHERE qna_id = #{qnaId}

SELECT qna_id AS qnaId, product_id AS productId, store_id AS storeId, writer_user_id AS writerUserId, title, content, qna_category AS qnaCategory, is_private AS isPrivate, status, answer_user_id AS answerUserId, answer_content AS answerContent, answered_at AS answeredAt, created_date AS createdDate, updated_date AS updatedDate FROM PRODUCT_QNA WHERE 1=1 AND store_id = #{storeId}
AND qna_category = #{qnaCategory}
AND status = #{status}
AND (title LIKE '%' || #{keyword} || '%' OR content LIKE '%' || #{keyword} || '%')
ORDER BY created_date DESC

